// Pixel load event listener
pmw.bus.on("pmw:load-pixels", () => {

	if (pmwDataLayer?.pixels?.snapchat?.pixel_id && !pmwDataLayer?.pixels?.snapchat?.loaded) {
		if (pmw.consent.canPixelBeFired("marketing", "Snapchat")) pmw.loadSnapchatPixel()
	}
})

// PaveView event
pmw.bus.on("pmw:pixel:page-view", (payload) => {

	try {
		if (pmw.canNotFireSnapchatEvent()) return
		if (!pmw.shouldFireBrowserPixel(payload, "snapchat")) return

		// Get Snapchat data from unified payload
		const snapchatData = payload.pixels?.snapchat;
		if (!snapchatData) {
			pmw.console.warn("Snapchat event data not found in payload for page-view");
			return;
		}

		let data = {
			client_dedup_id: snapchatData.event_id,
		}

		snaptr("track", "PAGE_VIEW", data)
		// pmw.console.log("Snapchat: PAGE_VIEW event sent", data)

	} catch (e) {
		console.error(e)
	}
})

// AddToCart event
pmw.bus.on("pmw:pixel:add-to-cart", (payload) => {

	try {
		if (pmw.canNotFireSnapchatEvent()) return
		if (!pmw.shouldFireBrowserPixel(payload, "snapchat")) return

		// Get Snapchat data from unified payload
		const snapchatData = payload.pixels?.snapchat;
		if (!snapchatData) {
			pmw.console.warn("Snapchat event data not found in payload for add_to_cart");
			return;
		}

		const product = payload.event_data?.product;
		if (!product) return;

		let data = {
			client_dedup_id: snapchatData.event_id,
			currency       : pmw.getProductCurrency(product),
			price          : product.price * product.quantity,
			number_items   : product.quantity,
			item_ids       : [pmw.getProductIdForSpecificPixel(product, "snapchat")],
		}

		snaptr("track", "ADD_CART", data)
		pmw.console.log("Snapchat Pixel: ADD_CART event sent", data)

	} catch (e) {
		console.error(e)
	}
})

// VIEW_CONTENT event
pmw.bus.on("pmw:pixel:view-item", (payload) => {

	try {
		if (pmw.canNotFireSnapchatEvent()) return
		if (!pmw.shouldFireBrowserPixel(payload, "snapchat")) return

		// Get Snapchat data from unified payload
		const snapchatData = payload.pixels?.snapchat;
		if (!snapchatData) {
			pmw.console.warn("Snapchat event data not found in payload for view_item");
			return;
		}

		const product = payload.event_data?.product;

		let data = {
			client_dedup_id: snapchatData.event_id,
		}

		if (product) {
			data.currency     = pmw.getProductCurrency(product)
			data.price        = product.price * product.quantity
			data.number_items = product.quantity
			data.item_ids     = [pmw.getProductIdForSpecificPixel(product, "snapchat")]
		}

		snaptr("track", "VIEW_CONTENT", data)
		pmw.console.log("Snapchat Pixel: VIEW_CONTENT event sent", data)

	} catch (e) {
		console.error(e)
	}
})

