// PURCHASE event. View order received page event
// Note: Server-side transmission is handled via PHP Conversions API, this only fires the browser pixel
pmw.bus.on("pmw:pixel:purchase", () => {

	try {
		if (pmw.canNotFireSnapchatEvent()) return
		if (!pmwDataLayer.order) return

		const data = {
			// Snap deduplicates a browser event against its CAPI twin by
			// matching client_dedup_id to the CAPI event_id, so this has to
			// carry the exact same value the Snapchat CAPI purchase sends
			// (Snapchat_CAPI::build_ssp_purchase_event_data and the adapter's
			// adaptPurchase). transaction_id stays the bare order ID, because
			// that is the order number Snap reports back.
			client_dedup_id: "pmw_" + pmwDataLayer.order.id.toString(),
			currency       : pmwDataLayer.order.currency,
			price          : pmwDataLayer.order.value.marketing,
			transaction_id : pmwDataLayer.order.id,
			item_ids       : pmw.getSnapchatOrderItemIds(),
			customer_status: pmwDataLayer.order.new_customer ? "new" : "returning",
		}

		snaptr("track", "PURCHASE", data)
		pmw.console.log("Snapchat Pixel: PURCHASE event sent", data)

	} catch (e) {
		console.error(e)
	}
})
